import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_EMBARCACION, MODELO_PUERTO, TABLA_EMBARCACIONES } from '../../models/puerto-embarcacion.model.mjs';

export async function buscarPuertoRepository(puertoId) {
  const { Item } = await MODELO_PUERTO.build(GetItemCommand)
    .key({ puertoId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarPuertoRepository(puertoId, minimo) {
  const { Items = [] } = await TABLA_EMBARCACIONES.build(QueryCommand)
    .entities(MODELO_EMBARCACION)
    .query({ index: 'PorPuerto', partition: puertoId })
    .options({ filters: { Embarcacion: { attr: 'esloraMetros', gte: minimo } } })
    .send();
  return Items;
}
